import { createHash, randomUUID } from "node:crypto";
import type { BusinessSession, BusinessSessionRunner } from "../ports/persistence.ts";
import type { BookSetId, TenantId } from "../../core/types.ts";
import { brandAccountId } from "../../core/types.ts";
import { DomainError, IdempotencyConflictError } from "../../core/types.ts";
import type { CommandEnvelope, CommandResult } from "../commands.ts";
import { canonicalJson, computeCommandHash, computeResultHash } from "../commands.ts";
import { postJournalInSession } from "./journal-command-service.ts";
type JournalLinePayload = { accountId: any; debitMinor?: number; creditMinor?: number };

export type PayrollCommandEnvelope<P> = CommandEnvelope<P> & { bookSetId: BookSetId };
type Session = BusinessSession;
type Scope = { tenantId: TenantId; bookSetId: BookSetId };

export interface EmployeeCreatePayload { employeeId?: string; employeeCode: string; legalName: string; joiningDate: string; exitDate?: string; workState: string; workLocation: string; panLastFour?: string; panFingerprint?: string; panVerificationStatus?: "UNVERIFIED" | "VERIFIED" | "REVIEW_REQUIRED"; uanLastFour?: string; uanVerificationStatus?: "NOT_APPLICABLE" | "UNVERIFIED" | "VERIFIED" | "REVIEW_REQUIRED"; esicLastFour?: string; esicVerificationStatus?: "NOT_APPLICABLE" | "UNVERIFIED" | "VERIFIED" | "REVIEW_REQUIRED"; bankLastFour?: string; bankFingerprint?: string; bankVerificationStatus?: "UNVERIFIED" | "VERIFIED" | "REVIEW_REQUIRED"; evidenceId?: string; }
export interface EmployeeResult { employeeId: string; employeeCode: string; legalName: string; pan: string | null; uan: string | null; esic: string | null; bankAccount: string | null; joiningDate: string; exitDate: string | null; workState: string; workLocation: string; }
export interface EmployeeProfilePayload { employeeId: string; profileType: "TAX" | "STATUTORY"; effectiveFrom: string; effectiveTo?: string; facts: Record<string, unknown>; verificationStatus?: "UNVERIFIED" | "VERIFIED" | "REVIEW_REQUIRED"; evidenceId?: string; }
export interface SalaryStructurePayload { structureId?: string; name: string; }
export interface SalaryVersionPayload { versionId?: string; structureId: string; versionNumber: number; effectiveFrom: string; effectiveTo?: string; prorationPolicy?: "NONE" | "PAYABLE_DAYS_OVER_PERIOD_DAYS" | "CALENDAR_DAYS"; }
export interface SalaryComponentInput { componentId?: string; componentCode: string; label: string; kind: "EARNING" | "EMPLOYEE_DEDUCTION" | "EMPLOYER_CONTRIBUTION" | "INFORMATIONAL"; basisType: "FIXED_MINOR" | "RATE_BPS"; fixedMinor?: number; rateBps?: number; basisComponentCode?: string; expenseAccountId?: string; payableAccountId?: string; liabilityAccountId?: string; }
export interface RuleSnapshotPayload { ruleSnapshotId?: string; jurisdiction: string; ruleType: "SALARY_TDS" | "EPF" | "ESI" | "PT" | "LWF"; effectiveFrom: string; effectiveTo?: string; officialSource: string; lawReference: string; ruleVersion: string; applicabilityFacts: Record<string, unknown>; rateBps?: number; capMinor?: number; basis: "GROSS" | "NAMED_COMPONENT" | "TAXABLE_INCOME" | "FIXED"; rounding?: "PAISE_HALF_UP" | "PAISE_DOWN" | "PAISE_UP"; status?: "VERIFIED" | "UNVERIFIED" | "TENTATIVE"; salaryTdsFacts?: { annualProjectedTaxMinor: number; priorDeductionMinor: number; remainingPeriods: number; currentAllocationMinor: number; paymentLaw: "INCOME_TAX_ACT_1961_S192" | "INCOME_TAX_ACT_2025_S392"; } }
export interface ClaimPayload { claimId?: string; employeeId: string; taxYear: string; category: string; amountMinor: number; evidenceId: string; }
export interface ClaimReviewPayload { claimId: string; status: "APPROVED" | "REJECTED"; observation: string; }
export interface PayRunEmployeeInput { employeeId: string; salaryVersionId: string; payableDays: number; periodDays: number; unpaidLeaveDays?: number; variableFacts?: Record<string, number>; ruleSnapshotIds?: string[]; }
export interface PayRunPreparePayload { payRunId?: string; periodStart: string; periodEnd: string; paymentDate: string; employees: PayRunEmployeeInput[]; }
export interface PayRunActionPayload { payRunId: string; }
export interface PayrollBankBatchPayload { batchId?: string; paymentDate: string; bankAccountId: string; allocations: Array<{ payRunEmployeeId: string; amountMinor: number }>; }
export interface BankExportPayload { batchId: string; presetId?: string; }
export interface RemittancePayload { remittanceId?: string; ruleType: RuleSnapshotPayload["ruleType"]; periodStart: string; periodEnd: string; liabilityAccountId: string; amountMinor: number; }
export interface RemittanceActionPayload { remittanceId: string; status: "EXPORTED" | "SUBMITTED" | "ACKNOWLEDGED" | "REJECTED"; evidenceId?: string; observation?: string; }

function iso(value: unknown, field: string): asserts value is string { if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value) || Number.isNaN(new Date(`${value}T00:00:00.000Z`).valueOf())) throw new DomainError("INVALID_PAYROLL_DATE", `${field} must be a valid ISO date`); }
function positive(value: unknown, field: string, allowZero = false): number { if (typeof value !== "number" || !Number.isSafeInteger(value) || (allowZero ? value < 0 : value <= 0)) throw new DomainError("INVALID_PAYROLL_AMOUNT", `${field} must be an integer minor amount`); return value; }
function bps(value: unknown, field: string): number { if (typeof value !== "number" || !Number.isSafeInteger(value) || value < 0 || value > 100000) throw new DomainError("INVALID_PAYROLL_RATE", `${field} must be between 0 and 100000 basis points`); return value; }
function safeAdd(a: number, b: number): number { const n = a + b; if (!Number.isSafeInteger(n)) throw new DomainError("PAYROLL_AMOUNT_UNSAFE", "payroll amount exceeds safe integer range"); return n; }
function roundRate(base: number, rate: number): number { const n = base * rate; if (!Number.isSafeInteger(n)) throw new DomainError("PAYROLL_AMOUNT_UNSAFE", "rate multiplication exceeds safe integer range"); return Math.floor((n + 5000) / 10000); }
function prorate(amount: number, policy: string, payableDays: number, periodDays: number): number { if (policy === "NONE") return amount; return Math.floor((amount * payableDays + Math.floor(periodDays / 2)) / periodDays); }
function mask(lastFour: unknown, label: string): string | null { return lastFour == null ? null : `${label} ****${String(lastFour).slice(-4)}`; }
function hash(value: unknown): string { return createHash("sha256").update(canonicalJson(value)).digest("hex"); }
function payloadHash(command: string, envelope: PayrollCommandEnvelope<unknown>): string { return computeCommandHash(command, envelope, envelope.payload); }
function assertEnvelope(envelope: PayrollCommandEnvelope<unknown>): void { if (envelope.schemaVersion !== 1 || !envelope.tenantId || !envelope.bookSetId || !envelope.requestId || !envelope.reason?.trim()) throw new DomainError("INVALID_COMMAND_ENVELOPE", "Payroll commands require schemaVersion, tenantId, bookSetId, requestId, actor, source, and reason"); }

async function idempotent<T>(session: Session, scope: Scope & { requestId: string }, requestHash: string, work: () => Promise<T>): Promise<CommandResult<T>> {
  const requestId = scope.requestId;
  const existing = await session.querySingle("SELECT request_hash, result_json, result_hash FROM idempotency_records WHERE tenant_id = ? AND request_id = ?", [scope.tenantId, requestId]);
  if (existing) { if (String(existing.request_hash) !== requestHash) throw new IdempotencyConflictError("same request_id with different payroll request hash"); const resultJson = String(existing.result_json); if (computeResultHash(resultJson) !== String(existing.result_hash)) throw new DomainError("IDEMPOTENCY_CORRUPT", "stored payroll result hash mismatch"); return { resultJson, resultHash: String(existing.result_hash), replayed: true }; }
  const result = await work(); const resultJson = canonicalJson(result); const resultHash = computeResultHash(resultJson); const now = new Date().toISOString();
  await session.execute("INSERT INTO idempotency_records (id, tenant_id, request_id, request_hash, result_json, result_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [randomUUID(), scope.tenantId, requestId, requestHash, resultJson, resultHash, now]);
  return { resultJson, resultHash };
}
async function scopeExists(session: Session, scope: Scope): Promise<void> { const row = await session.querySingle("SELECT id, lifecycle FROM book_sets WHERE id = ? AND tenant_id = ?", [scope.bookSetId, scope.tenantId]); if (!row) throw new DomainError("BOOK_SET_NOT_FOUND", "BookSet does not belong to tenant"); if (String(row.lifecycle) !== "ACTIVE") throw new DomainError("BOOK_SET_INACTIVE", "BookSet must be ACTIVE"); }
async function audit(session: Session, envelope: PayrollCommandEnvelope<unknown>, entityType: string, entityId: string, resultHash: string, action: string): Promise<void> { const now = new Date().toISOString(); await session.execute("INSERT INTO audit_records (id, tenant_id, book_set_id, command, action, actor_type, actor_id, source, reason, request_id, canonical_before_hash, canonical_after_hash, change_summary, committed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId, action, action, envelope.actor.kind, envelope.actor.id, envelope.source, envelope.reason, envelope.requestId, resultHash, JSON.stringify({ entityType, entityId }), now, now]); }

export async function createEmployee(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<EmployeeCreatePayload>): Promise<CommandResult<EmployeeResult>> { assertEnvelope(envelope); const p = envelope.payload; if (!p || !p.employeeCode?.trim() || !p.legalName?.trim()) throw new DomainError("INVALID_EMPLOYEE", "employeeCode and legalName are required"); iso(p.joiningDate, "joiningDate"); if (p.exitDate) iso(p.exitDate, "exitDate"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.employee.create", envelope), async () => { await scopeExists(s, envelope); const id = p.employeeId ?? randomUUID(); const now = new Date().toISOString(); await s.execute("INSERT INTO payroll_employees (id, tenant_id, book_set_id, employee_code, legal_name, joining_date, exit_date, work_state, work_location, pan_last_four, pan_fingerprint, pan_verification_status, uan_last_four, uan_verification_status, esic_last_four, esic_verification_status, bank_last_four, bank_fingerprint, bank_verification_status, evidence_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, envelope.tenantId, envelope.bookSetId, p.employeeCode.trim(), p.legalName.trim(), p.joiningDate, p.exitDate ?? null, p.workState, p.workLocation, p.panLastFour ?? null, p.panFingerprint ?? null, p.panVerificationStatus ?? "UNVERIFIED", p.uanLastFour ?? null, p.uanVerificationStatus ?? "NOT_APPLICABLE", p.esicLastFour ?? null, p.esicVerificationStatus ?? "NOT_APPLICABLE", p.bankLastFour ?? null, p.bankFingerprint ?? null, p.bankVerificationStatus ?? "UNVERIFIED", p.evidenceId ?? null, now, now]); const result = { employeeId: id, employeeCode: p.employeeCode.trim(), legalName: p.legalName.trim(), pan: mask(p.panLastFour, "PAN"), uan: mask(p.uanLastFour, "UAN"), esic: mask(p.esicLastFour, "ESIC"), bankAccount: mask(p.bankLastFour, "BANK"), joiningDate: p.joiningDate, exitDate: p.exitDate ?? null, workState: p.workState, workLocation: p.workLocation }; await audit(s, envelope, "payroll_employee", id, hash(result), "payroll.employee.create"); return result; })); }

export async function getEmployee(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, employeeId: string): Promise<EmployeeResult> { return sessionRunner.withBusinessSession("read", async (s) => { const r = await s.querySingle("SELECT id, employee_code, legal_name, joining_date, exit_date, work_state, work_location, pan_last_four, uan_last_four, esic_last_four, bank_last_four FROM payroll_employees WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [employeeId, tenantId, bookSetId]); if (!r) throw new DomainError("EMPLOYEE_NOT_FOUND", "Employee does not belong to tenant and BookSet"); return { employeeId: String(r.id), employeeCode: String(r.employee_code), legalName: String(r.legal_name), pan: mask(r.pan_last_four, "PAN"), uan: mask(r.uan_last_four, "UAN"), esic: mask(r.esic_last_four, "ESIC"), bankAccount: mask(r.bank_last_four, "BANK"), joiningDate: String(r.joining_date), exitDate: r.exit_date == null ? null : String(r.exit_date), workState: String(r.work_state), workLocation: String(r.work_location) }; }); }
export async function listEmployees(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId): Promise<EmployeeResult[]> { return sessionRunner.withBusinessSession("read", async (s) => { const rows = await s.query("SELECT id, employee_code, legal_name, joining_date, exit_date, work_state, work_location, pan_last_four, uan_last_four, esic_last_four, bank_last_four FROM payroll_employees WHERE tenant_id = ? AND book_set_id = ? ORDER BY employee_code, id", [tenantId, bookSetId]); return rows.rows.map((r) => ({ employeeId: String(r.id), employeeCode: String(r.employee_code), legalName: String(r.legal_name), pan: mask(r.pan_last_four, "PAN"), uan: mask(r.uan_last_four, "UAN"), esic: mask(r.esic_last_four, "ESIC"), bankAccount: mask(r.bank_last_four, "BANK"), joiningDate: String(r.joining_date), exitDate: r.exit_date == null ? null : String(r.exit_date), workState: String(r.work_state), workLocation: String(r.work_location) })); }); }

export async function createEmployeeProfile(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<EmployeeProfilePayload>): Promise<CommandResult<{ profileId: string; canonicalHash: string }>> { assertEnvelope(envelope); const p = envelope.payload; if (!p.employeeId || !p.facts || typeof p.facts !== "object") throw new DomainError("INVALID_EMPLOYEE_PROFILE", "employeeId and facts are required"); iso(p.effectiveFrom, "effectiveFrom"); if (p.effectiveTo) iso(p.effectiveTo, "effectiveTo"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.employee-profile.create", envelope), async () => { const employee = await s.querySingle("SELECT id FROM payroll_employees WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.employeeId, envelope.tenantId, envelope.bookSetId]); if (!employee) throw new DomainError("EMPLOYEE_NOT_FOUND", "Employee does not belong to tenant and BookSet"); const id = randomUUID(); const canonicalHash = hash({ ...p, tenantId: envelope.tenantId, bookSetId: envelope.bookSetId }); await s.execute("INSERT INTO payroll_employee_profiles (id, tenant_id, book_set_id, employee_id, profile_type, effective_from, effective_to, facts_json, verification_status, evidence_id, canonical_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, envelope.tenantId, envelope.bookSetId, p.employeeId, p.profileType, p.effectiveFrom, p.effectiveTo ?? null, canonicalJson(p.facts), p.verificationStatus ?? "UNVERIFIED", p.evidenceId ?? null, canonicalHash, new Date().toISOString()]); await audit(s, envelope, "payroll_employee_profile", id, canonicalHash, "payroll.employee-profile.create"); return { profileId: id, canonicalHash }; })); }

export async function createSalaryStructure(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<SalaryStructurePayload>): Promise<CommandResult<{ structureId: string }>> { assertEnvelope(envelope); if (!envelope.payload.name?.trim()) throw new DomainError("INVALID_SALARY_STRUCTURE", "name is required"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.salary-structure.create", envelope), async () => { const id = envelope.payload.structureId ?? randomUUID(); await s.execute("INSERT INTO payroll_salary_structures (id, tenant_id, book_set_id, name, created_at) VALUES (?, ?, ?, ?, ?)", [id, envelope.tenantId, envelope.bookSetId, envelope.payload.name.trim(), new Date().toISOString()]); const result = { structureId: id }; await audit(s, envelope, "payroll_salary_structure", id, hash(result), "payroll.salary-structure.create"); return result; })); }
export async function createSalaryVersion(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<SalaryVersionPayload>, components: SalaryComponentInput[] = []): Promise<CommandResult<{ versionId: string; componentIds: string[] }>> { assertEnvelope(envelope); const p = envelope.payload; iso(p.effectiveFrom, "effectiveFrom"); if (p.effectiveTo) iso(p.effectiveTo, "effectiveTo"); if (!Number.isSafeInteger(p.versionNumber) || p.versionNumber < 1) throw new DomainError("INVALID_SALARY_VERSION", "versionNumber must be positive"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.salary-version.create", envelope), async () => { const structure = await s.querySingle("SELECT id FROM payroll_salary_structures WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.structureId, envelope.tenantId, envelope.bookSetId]); if (!structure) throw new DomainError("SALARY_STRUCTURE_NOT_FOUND", "salary structure does not belong to tenant and BookSet"); const id = p.versionId ?? randomUUID(); const componentIds: string[] = []; const versionHash = hash({ ...p, components }); await s.execute("INSERT INTO payroll_salary_versions (id, tenant_id, book_set_id, structure_id, version_number, effective_from, effective_to, proration_policy, canonical_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, envelope.tenantId, envelope.bookSetId, p.structureId, p.versionNumber, p.effectiveFrom, p.effectiveTo ?? null, p.prorationPolicy ?? "NONE", versionHash, new Date().toISOString()]); for (const c of components) { if (c.basisType === "FIXED_MINOR") positive(c.fixedMinor, `${c.componentCode}.fixedMinor`, true); else { bps(c.rateBps, `${c.componentCode}.rateBps`); if (!c.basisComponentCode) throw new DomainError("INVALID_SALARY_COMPONENT", "RATE_BPS requires basisComponentCode"); } if ((c.kind === "EARNING" || c.kind === "EMPLOYER_CONTRIBUTION") && !c.expenseAccountId) throw new DomainError("INVALID_SALARY_COMPONENT", `${c.componentCode} requires expenseAccountId`); if (c.kind === "EMPLOYER_CONTRIBUTION" && !c.liabilityAccountId) throw new DomainError("INVALID_SALARY_COMPONENT", `${c.componentCode} requires liabilityAccountId`); if (c.kind === "EMPLOYEE_DEDUCTION" && !c.liabilityAccountId) throw new DomainError("INVALID_SALARY_COMPONENT", `${c.componentCode} requires liabilityAccountId`); const componentId = c.componentId ?? randomUUID(); componentIds.push(componentId); await s.execute("INSERT INTO payroll_salary_components (id, tenant_id, book_set_id, version_id, component_code, label, kind, basis_type, fixed_minor, rate_bps, basis_component_code, expense_account_id, payable_account_id, liability_account_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [componentId, envelope.tenantId, envelope.bookSetId, id, c.componentCode, c.label, c.kind, c.basisType, c.fixedMinor ?? null, c.rateBps ?? null, c.basisComponentCode ?? null, c.expenseAccountId ?? null, c.payableAccountId ?? null, c.liabilityAccountId ?? null, new Date().toISOString()]); } const result = { versionId: id, componentIds }; await audit(s, envelope, "payroll_salary_version", id, hash(result), "payroll.salary-version.create"); return result; })); }

export async function createRuleSnapshot(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<RuleSnapshotPayload>): Promise<CommandResult<{ ruleSnapshotId: string; canonicalHash: string }>> { assertEnvelope(envelope); const p = envelope.payload; iso(p.effectiveFrom, "effectiveFrom"); if (p.effectiveTo) iso(p.effectiveTo, "effectiveTo"); if (!p.officialSource?.trim() || !p.lawReference?.trim() || !p.ruleVersion?.trim()) throw new DomainError("INVALID_PAYROLL_RULE", "official source, law reference, and rule version are required"); if (p.rateBps !== undefined) bps(p.rateBps, "rateBps"); if (p.salaryTdsFacts) { positive(p.salaryTdsFacts.annualProjectedTaxMinor, "annualProjectedTaxMinor", true); positive(p.salaryTdsFacts.priorDeductionMinor, "priorDeductionMinor", true); positive(p.salaryTdsFacts.remainingPeriods, "remainingPeriods"); positive(p.salaryTdsFacts.currentAllocationMinor, "currentAllocationMinor", true); if (p.salaryTdsFacts.priorDeductionMinor + p.salaryTdsFacts.currentAllocationMinor > p.salaryTdsFacts.annualProjectedTaxMinor) throw new DomainError("INVALID_SALARY_TDS_ARITHMETIC", "prior deduction plus current allocation exceeds projected annual tax"); }
  return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.rule-snapshot.create", envelope), async () => { const id = p.ruleSnapshotId ?? randomUUID(); const canonicalHash = hash({ ...p, tenantId: envelope.tenantId, bookSetId: envelope.bookSetId }); await s.execute("INSERT INTO payroll_rule_snapshots (id, tenant_id, book_set_id, jurisdiction, rule_type, effective_from, effective_to, official_source, law_reference, rule_version, applicability_facts_json, rate_bps, cap_minor, basis, rounding, status, salary_tds_facts_json, canonical_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [id, envelope.tenantId, envelope.bookSetId, p.jurisdiction, p.ruleType, p.effectiveFrom, p.effectiveTo ?? null, p.officialSource, p.lawReference, p.ruleVersion, canonicalJson(p.applicabilityFacts), p.rateBps ?? null, p.capMinor ?? null, p.basis, p.rounding ?? "PAISE_HALF_UP", p.status ?? "UNVERIFIED", p.salaryTdsFacts ? canonicalJson(p.salaryTdsFacts) : null, canonicalHash, new Date().toISOString()]); await audit(s, envelope, "payroll_rule_snapshot", id, canonicalHash, "payroll.rule-snapshot.create"); return { ruleSnapshotId: id, canonicalHash }; })); }

export async function createClaim(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<ClaimPayload>): Promise<CommandResult<{ claimId: string; status: "PENDING" }>> { assertEnvelope(envelope); const p = envelope.payload; positive(p.amountMinor, "amountMinor", true); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.claim.create", envelope), async () => { const employee = await s.querySingle("SELECT id FROM payroll_employees WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.employeeId, envelope.tenantId, envelope.bookSetId]); if (!employee) throw new DomainError("EMPLOYEE_NOT_FOUND", "Employee does not belong to tenant and BookSet"); const id = p.claimId ?? randomUUID(); await s.execute("INSERT INTO payroll_claims (id, tenant_id, book_set_id, employee_id, tax_year, category, amount_minor, evidence_id, status, reviewer_id, review_observation, reviewed_at, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'PENDING', NULL, NULL, NULL, ?)", [id, envelope.tenantId, envelope.bookSetId, p.employeeId, p.taxYear, p.category, p.amountMinor, p.evidenceId, new Date().toISOString()]); await audit(s, envelope, "payroll_claim", id, hash({ id, status: "PENDING" }), "payroll.claim.create"); return { claimId: id, status: "PENDING" as const }; })); }
export async function reviewClaim(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<ClaimReviewPayload>): Promise<CommandResult<{ claimId: string; status: string }>> { assertEnvelope(envelope); if (!envelope.payload.observation?.trim()) throw new DomainError("INVALID_CLAIM_REVIEW", "observation is required"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.claim.review", envelope), async () => { const claim = await s.querySingle("SELECT id, status FROM payroll_claims WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.claimId, envelope.tenantId, envelope.bookSetId]); if (!claim) throw new DomainError("CLAIM_NOT_FOUND", "claim does not belong to tenant and BookSet"); if (String(claim.status) !== "PENDING") throw new DomainError("CLAIM_ALREADY_REVIEWED", "claim review is append-only and cannot be changed"); await s.execute("UPDATE payroll_claims SET status = ?, reviewer_id = ?, review_observation = ?, reviewed_at = ? WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.status, envelope.actor.id, envelope.payload.observation, new Date().toISOString(), envelope.payload.claimId, envelope.tenantId, envelope.bookSetId]); const result = { claimId: envelope.payload.claimId, status: envelope.payload.status }; await audit(s, envelope, "payroll_claim", envelope.payload.claimId, hash(result), "payroll.claim.review"); return result; })); }

type ComputedEmployee = { input: PayRunEmployeeInput; employeeRow: Record<string, unknown>; versionRow: Record<string, unknown>; components: Record<string, unknown>[]; lines: Array<{ component: Record<string, unknown>; amount: number; facts: Record<string, unknown> }>; gross: number; deductions: number; employer: number; net: number; ruleIds: string[] };
async function computeEmployee(s: Session, scope: Scope, periodStart: string, periodEnd: string, paymentDate: string, input: PayRunEmployeeInput): Promise<ComputedEmployee> { positive(input.periodDays, "periodDays"); positive(input.payableDays, "payableDays", true); positive(input.unpaidLeaveDays ?? 0, "unpaidLeaveDays", true); if (input.payableDays > input.periodDays || (input.unpaidLeaveDays ?? 0) > input.periodDays) throw new DomainError("INVALID_PAYROLL_DAYS", "payableDays and unpaidLeaveDays must not exceed periodDays"); const employee = await s.querySingle("SELECT id, legal_name, employee_code, joining_date, exit_date FROM payroll_employees WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [input.employeeId, scope.tenantId, scope.bookSetId]); if (!employee) throw new DomainError("EMPLOYEE_NOT_FOUND", "employee does not belong to tenant and BookSet"); const version = await s.querySingle("SELECT id, proration_policy, effective_from, effective_to FROM payroll_salary_versions WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [input.salaryVersionId, scope.tenantId, scope.bookSetId]); if (!version || String(version.effective_from) > periodEnd || (version.effective_to != null && String(version.effective_to) < periodStart)) throw new DomainError("SALARY_VERSION_NOT_EFFECTIVE", "salary version is not effective for the pay period"); const components = (await s.query("SELECT id, component_code, label, kind, basis_type, fixed_minor, rate_bps, basis_component_code, expense_account_id, payable_account_id, liability_account_id FROM payroll_salary_components WHERE version_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY component_code, id", [input.salaryVersionId, scope.tenantId, scope.bookSetId])).rows; const byCode = new Map<string, number>(); const lines: ComputedEmployee["lines"] = []; let gross = 0; let deductions = 0; let employer = 0; for (const component of components) { const code = String(component.component_code); const variable = input.variableFacts?.[code]; const baseAmount = variable !== undefined ? positive(variable, `${code}.variable`, true) : component.basis_type === "FIXED_MINOR" ? positive(Number(component.fixed_minor), `${code}.fixedMinor`, true) : roundRate(byCode.get(String(component.basis_component_code)) ?? 0, bps(Number(component.rate_bps), `${code}.rateBps`)); const amount = prorate(baseAmount, String(version.proration_policy), input.payableDays, input.periodDays); byCode.set(code, amount); lines.push({ component, amount, facts: { basisType: component.basis_type, fixedMinor: component.fixed_minor ?? null, rateBps: component.rate_bps ?? null, basisComponentCode: component.basis_component_code ?? null, payableDays: input.payableDays, periodDays: input.periodDays, amountMinor: amount } }); if (component.kind === "EARNING") gross = safeAdd(gross, amount); else if (component.kind === "EMPLOYEE_DEDUCTION") deductions = safeAdd(deductions, amount); else if (component.kind === "EMPLOYER_CONTRIBUTION") employer = safeAdd(employer, amount); }
  const ruleIds = [...(input.ruleSnapshotIds ?? [])].sort(); if (ruleIds.length === 0) throw new DomainError("REVIEW_REQUIRED", "each payroll employee requires explicit effective rule snapshot IDs"); for (const ruleId of ruleIds) { const rule = await s.querySingle("SELECT id, status, effective_from, effective_to, rule_type, salary_tds_facts_json FROM payroll_rule_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [ruleId, scope.tenantId, scope.bookSetId]); if (!rule) throw new DomainError("PAYROLL_RULE_MISSING", `rule snapshot is missing: ${ruleId}`); if (String(rule.status) !== "VERIFIED") throw new DomainError("REVIEW_REQUIRED", `payroll rule requires review: ${ruleId}`); if (String(rule.effective_from) > paymentDate || (rule.effective_to != null && String(rule.effective_to) < paymentDate)) throw new DomainError("PAYROLL_RULE_STALE", `payroll rule is not effective on payment date: ${ruleId}`); if (String(rule.rule_type) === "SALARY_TDS" && rule.salary_tds_facts_json) { const facts = JSON.parse(String(rule.salary_tds_facts_json)) as { annualProjectedTaxMinor: number; priorDeductionMinor: number; currentAllocationMinor: number }; if (facts.priorDeductionMinor + facts.currentAllocationMinor > facts.annualProjectedTaxMinor) throw new DomainError("INVALID_SALARY_TDS_ARITHMETIC", "salary TDS snapshot arithmetic is invalid"); deductions = safeAdd(deductions, positive(facts.currentAllocationMinor, "currentAllocationMinor", true)); } } if (deductions > gross) throw new DomainError("NEGATIVE_NET_PAY", "employee deductions exceed gross pay"); return { input, employeeRow: employee, versionRow: version, components, lines, gross, deductions, employer, net: gross - deductions, ruleIds }; }

export async function preparePayRun(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<PayRunPreparePayload>): Promise<CommandResult<{ payRunId: string; status: "PREPARED"; calculationHash: string }>> { assertEnvelope(envelope); const p = envelope.payload; iso(p.periodStart, "periodStart"); iso(p.periodEnd, "periodEnd"); iso(p.paymentDate, "paymentDate"); if (p.periodEnd < p.periodStart || p.paymentDate < p.periodEnd || !p.employees?.length) throw new DomainError("INVALID_PAY_RUN", "pay period, payment date, and employees are required"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.pay-run.prepare", envelope), async () => { await scopeExists(s, envelope); const runId = p.payRunId ?? randomUUID(); const computed: ComputedEmployee[] = []; for (const input of p.employees) computed.push(await computeEmployee(s, envelope, p.periodStart, p.periodEnd, p.paymentDate, input)); const inputHash = hash({ tenantId: envelope.tenantId, bookSetId: envelope.bookSetId, ...p }); const calculationHash = hash(computed.map((e) => ({ employeeId: e.input.employeeId, gross: e.gross, deductions: e.deductions, employer: e.employer, net: e.net, ruleIds: e.ruleIds, lines: e.lines.map((l) => ({ code: l.component.component_code, amount: l.amount, facts: l.facts })) }))); const now = new Date().toISOString(); await s.execute("INSERT INTO payroll_pay_runs (id, tenant_id, book_set_id, period_start, period_end, payment_date, status, input_hash, calculation_hash, journal_id, created_at, approved_at, posted_at) VALUES (?, ?, ?, ?, ?, ?, 'PREPARED', ?, ?, NULL, ?, NULL, '')", [runId, envelope.tenantId, envelope.bookSetId, p.periodStart, p.periodEnd, p.paymentDate, inputHash, calculationHash, now]); for (const e of computed) { const employeeRunId = randomUUID(); await s.execute("INSERT INTO payroll_pay_run_employees (id, tenant_id, book_set_id, pay_run_id, employee_id, salary_version_id, payable_days, period_days, unpaid_leave_days, variable_facts_json, gross_minor, employee_deduction_minor, employer_contribution_minor, net_minor, rule_ids_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [employeeRunId, envelope.tenantId, envelope.bookSetId, runId, e.input.employeeId, e.input.salaryVersionId, e.input.payableDays, e.input.periodDays, e.input.unpaidLeaveDays ?? 0, canonicalJson(e.input.variableFacts ?? {}), e.gross, e.deductions, e.employer, e.net, canonicalJson(e.ruleIds), now]); for (const line of e.lines) await s.execute("INSERT INTO payroll_component_lines (id, tenant_id, book_set_id, pay_run_employee_id, component_id, amount_minor, calculation_facts_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId, employeeRunId, line.component.id, line.amount, canonicalJson(line.facts), now]); } const result = { payRunId: runId, status: "PREPARED" as const, calculationHash }; await audit(s, envelope, "payroll_pay_run", runId, hash(result), "payroll.pay-run.prepare"); return result; })); }

async function storedPayRunCalculationHash(s: Session, runId: string, scope: Scope): Promise<string> {
  const employees = await s.query("SELECT e.id, e.employee_id, e.gross_minor, e.employee_deduction_minor, e.employer_contribution_minor, e.net_minor, e.rule_ids_json FROM payroll_pay_run_employees e WHERE e.pay_run_id = ? AND e.tenant_id = ? AND e.book_set_id = ? ORDER BY e.employee_id, e.id", [runId, scope.tenantId, scope.bookSetId]);
  const values = [];
  for (const employee of employees.rows) {
    const lines = await s.query("SELECT c.component_code, l.amount_minor, l.calculation_facts_json FROM payroll_component_lines l JOIN payroll_salary_components c ON c.id = l.component_id AND c.tenant_id = l.tenant_id AND c.book_set_id = l.book_set_id WHERE l.pay_run_employee_id = ? AND l.tenant_id = ? AND l.book_set_id = ? ORDER BY l.id", [employee.id, scope.tenantId, scope.bookSetId]);
    values.push({ employeeId: String(employee.employee_id), gross: Number(employee.gross_minor), deductions: Number(employee.employee_deduction_minor), employer: Number(employee.employer_contribution_minor), net: Number(employee.net_minor), ruleIds: (JSON.parse(String(employee.rule_ids_json)) as string[]).slice().sort(), lines: lines.rows.map((line) => ({ code: String(line.component_code), amount: Number(line.amount_minor), facts: JSON.parse(String(line.calculation_facts_json)) })) });
  }
  return hash(values);
}

export async function approvePayRun(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<PayRunActionPayload>): Promise<CommandResult<{ payRunId: string; status: "APPROVED" }>> { assertEnvelope(envelope); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.pay-run.approve", envelope), async () => { const run = await s.querySingle("SELECT id, status, payment_date, calculation_hash FROM payroll_pay_runs WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.payRunId, envelope.tenantId, envelope.bookSetId]); if (!run) throw new DomainError("PAY_RUN_NOT_FOUND", "pay run does not belong to tenant and BookSet"); if (String(run.status) !== "PREPARED") throw new DomainError("INVALID_PAY_RUN_STATE", "only PREPARED pay runs can be approved"); const pending = await s.querySingle("SELECT id FROM payroll_claims c WHERE c.tenant_id = ? AND c.book_set_id = ? AND c.status = 'PENDING' LIMIT 1", [envelope.tenantId, envelope.bookSetId]); if (pending) throw new DomainError("REVIEW_REQUIRED", "pending employee claim blocks pay-run approval"); const employees = await s.query("SELECT rule_ids_json FROM payroll_pay_run_employees WHERE pay_run_id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.payRunId, envelope.tenantId, envelope.bookSetId]); for (const employee of employees.rows) { for (const ruleId of JSON.parse(String(employee.rule_ids_json)) as string[]) { const rule = await s.querySingle("SELECT status, effective_from, effective_to FROM payroll_rule_snapshots WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [ruleId, envelope.tenantId, envelope.bookSetId]); if (!rule || String(rule.status) !== "VERIFIED") throw new DomainError("REVIEW_REQUIRED", `payroll rule requires review: ${ruleId}`); if (String(rule.effective_from) > String(run.payment_date) || (rule.effective_to != null && String(rule.effective_to) < String(run.payment_date))) throw new DomainError("PAYROLL_RULE_STALE", `payroll rule is not effective on payment date: ${ruleId}`); } } const calculationHash = await storedPayRunCalculationHash(s, envelope.payload.payRunId, envelope); if (String(run.calculation_hash) !== calculationHash) throw new DomainError("PAYROLL_CALCULATION_HASH_MISMATCH", "pay-run facts or component lines changed after preparation"); const now = new Date().toISOString(); await s.execute("UPDATE payroll_pay_runs SET status = 'APPROVED', approved_at = ? WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [now, envelope.payload.payRunId, envelope.tenantId, envelope.bookSetId]); const result = { payRunId: envelope.payload.payRunId, status: "APPROVED" as const }; await audit(s, envelope, "payroll_pay_run", envelope.payload.payRunId, hash(result), "payroll.pay-run.approve"); return result; })); }

async function payableAccounts(s: Session, scope: Scope, accountIds: string[]): Promise<void> { for (const id of accountIds) { const row = await s.querySingle("SELECT id, account_type, archived_at FROM accounts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [id, scope.tenantId, scope.bookSetId]); if (!row) throw new DomainError("ACCOUNT_SCOPE_MISMATCH", `payroll account does not belong to tenant and BookSet: ${id}`); if (row.archived_at != null) throw new DomainError("ACCOUNT_ARCHIVED", `payroll account is archived: ${id}`); } }
async function payrollAccount(s: Session, scope: Scope, accountId: string, expectedType: "ASSET" | "LIABILITY" | "EXPENSE"): Promise<void> { const row = await s.querySingle("SELECT account_type FROM accounts WHERE id = ? AND tenant_id = ? AND book_set_id = ? AND archived_at IS NULL", [accountId, scope.tenantId, scope.bookSetId]); if (!row) throw new DomainError("ACCOUNT_SCOPE_MISMATCH", `payroll account does not belong to tenant and BookSet: ${accountId}`); if (String(row.account_type) !== expectedType) throw new DomainError("INVALID_ACCOUNT_CLASS", `payroll account must be ${expectedType}: ${accountId}`); }
export async function postPayRun(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<PayRunActionPayload>): Promise<CommandResult<{ payRunId: string; status: "POSTED"; journalId: string }>> { assertEnvelope(envelope); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.pay-run.post", envelope), async () => { const run = await s.querySingle("SELECT id, status, period_end, payment_date, calculation_hash FROM payroll_pay_runs WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.payRunId, envelope.tenantId, envelope.bookSetId]); if (!run) throw new DomainError("PAY_RUN_NOT_FOUND", "pay run does not belong to tenant and BookSet"); if (String(run.status) !== "APPROVED") throw new DomainError("INVALID_PAY_RUN_STATE", "only APPROVED pay runs can be posted"); const employees = await s.query("SELECT id, employee_id, gross_minor, employee_deduction_minor, employer_contribution_minor, net_minor FROM payroll_pay_run_employees WHERE pay_run_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY employee_id, id", [envelope.payload.payRunId, envelope.tenantId, envelope.bookSetId]); const lines: JournalLinePayload[] = []; const accountIds: string[] = []; const accountsFor = await s.query("SELECT l.amount_minor, c.kind, c.expense_account_id, c.liability_account_id, c.payable_account_id FROM payroll_component_lines l JOIN payroll_salary_components c ON c.id = l.component_id AND c.tenant_id = l.tenant_id AND c.book_set_id = l.book_set_id JOIN payroll_pay_run_employees e ON e.id = l.pay_run_employee_id AND e.tenant_id = l.tenant_id AND e.book_set_id = l.book_set_id WHERE e.pay_run_id = ? AND l.tenant_id = ? AND l.book_set_id = ? ORDER BY l.id", [envelope.payload.payRunId, envelope.tenantId, envelope.bookSetId]); let totalNet = 0; for (const e of employees.rows) { totalNet = safeAdd(totalNet, Number(e.net_minor)); } for (const row of accountsFor.rows) { const amount = Number(row.amount_minor); if (!amount) continue; const kind = String(row.kind); const accountId = kind === "EMPLOYEE_DEDUCTION" ? String(row.liability_account_id) : String(row.expense_account_id); if (accountId && accountId !== "null") { if (kind === "EARNING" || kind === "EMPLOYER_CONTRIBUTION") await payrollAccount(s, envelope, accountId, "EXPENSE"); if (kind === "EMPLOYEE_DEDUCTION") await payrollAccount(s, envelope, accountId, "LIABILITY"); lines.push({ accountId, debitMinor: kind === "EARNING" || kind === "EMPLOYER_CONTRIBUTION" ? amount : undefined, creditMinor: kind === "EMPLOYEE_DEDUCTION" ? amount : undefined }); accountIds.push(accountId); if (kind === "EMPLOYER_CONTRIBUTION" && row.liability_account_id) { await payrollAccount(s, envelope, String(row.liability_account_id), "LIABILITY"); lines.push({ accountId: row.liability_account_id, creditMinor: amount }); accountIds.push(String(row.liability_account_id)); } } } const payable = await s.querySingle("SELECT payable_account_id FROM payroll_salary_components WHERE payable_account_id IS NOT NULL AND tenant_id = ? AND book_set_id = ? ORDER BY id LIMIT 1", [envelope.tenantId, envelope.bookSetId]); if (!payable) throw new DomainError("PAYROLL_NET_PAYABLE_ACCOUNT_MISSING", "a salary component must name the employee net-pay payable account"); await payrollAccount(s, envelope, String(payable.payable_account_id), "LIABILITY"); lines.push({ accountId: String(payable.payable_account_id), creditMinor: totalNet }); accountIds.push(String(payable.payable_account_id)); await payableAccounts(s, envelope, accountIds); const journalId = await postJournalInSession(s, { tenantId: envelope.tenantId, bookSetId: envelope.bookSetId, postingDate: String(run.period_end), reference: `PAYROLL:${envelope.payload.payRunId}`, narration: "India payroll posting", lines }); const now = new Date().toISOString(); await s.execute("UPDATE payroll_pay_runs SET status = 'POSTED', journal_id = ?, posted_at = ? WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [journalId, now, envelope.payload.payRunId, envelope.tenantId, envelope.bookSetId]); for (const e of employees.rows) { const slip = await renderPayslip(s, envelope, String(e.id), String(run.period_end), String(run.payment_date)); await s.execute("INSERT INTO payroll_payslips (id, tenant_id, book_set_id, pay_run_employee_id, payslip_number, rendered_text, rendered_html, evidence_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId, String(e.id), `PS-${envelope.payload.payRunId}-${String(e.employee_id)}`, slip.text, slip.html, slip.evidenceHash, now]); } const result = { payRunId: envelope.payload.payRunId, status: "POSTED" as const, journalId }; await audit(s, envelope, "payroll_pay_run", envelope.payload.payRunId, hash(result), "payroll.pay-run.post"); return result; })); }

async function renderPayslip(s: Session, envelope: Scope, payRunEmployeeId: string, periodEnd: string, paymentDate: string): Promise<{ text: string; html: string; evidenceHash: string }> { const employee = await s.querySingle("SELECT e.employee_code, e.legal_name, e.pan_last_four, p.period_start, p.period_end, p.payment_date, r.gross_minor, r.employee_deduction_minor, r.employer_contribution_minor, r.net_minor FROM payroll_pay_run_employees r JOIN payroll_employees e ON e.id = r.employee_id AND e.tenant_id = r.tenant_id AND e.book_set_id = r.book_set_id JOIN payroll_pay_runs p ON p.id = r.pay_run_id AND p.tenant_id = r.tenant_id AND p.book_set_id = r.book_set_id WHERE r.id = ? AND r.tenant_id = ? AND r.book_set_id = ?", [payRunEmployeeId, envelope.tenantId, envelope.bookSetId]); if (!employee) throw new DomainError("PAYSLIP_SOURCE_MISSING", "payroll employee facts are missing"); const components = await s.query("SELECT c.component_code, c.label, c.kind, l.amount_minor FROM payroll_component_lines l JOIN payroll_salary_components c ON c.id = l.component_id AND c.tenant_id = l.tenant_id AND c.book_set_id = l.book_set_id WHERE l.pay_run_employee_id = ? AND l.tenant_id = ? AND l.book_set_id = ? ORDER BY c.component_code, c.id", [payRunEmployeeId, envelope.tenantId, envelope.bookSetId]); const rows = components.rows.map((c) => `${String(c.component_code)}|${String(c.kind)}|${Number(c.amount_minor)}`).join("\n"); const text = [`Employee: ${employee.legal_name} (${employee.employee_code})`, `PAN: ${mask(employee.pan_last_four, "PAN") ?? "NOT PROVIDED"}`, `Pay period: ${employee.period_start} to ${employee.period_end}`, `Payment date: ${paymentDate}`, "Components:", rows, `Gross: ${employee.gross_minor}`, `Deductions: ${employee.employee_deduction_minor}`, `Employer contributions: ${employee.employer_contribution_minor}`, `Net pay: ${employee.net_minor}`, `Evidence: ${hash({ employee, rows, periodEnd, paymentDate })}`].join("\n"); const html = `<article><h1>Salary payslip</h1><p>Employee: ${String(employee.legal_name)} (${String(employee.employee_code)})</p><p>PAN: ${mask(employee.pan_last_four, "PAN") ?? "NOT PROVIDED"}</p><p>Pay period: ${String(employee.period_start)} to ${String(employee.period_end)}</p><p>Payment date: ${paymentDate}</p><pre>${rows}</pre><p>Gross: ${employee.gross_minor}</p><p>Deductions: ${employee.employee_deduction_minor}</p><p>Employer contributions: ${employee.employer_contribution_minor}</p><p>Net pay: ${employee.net_minor}</p></article>`; return { text, html, evidenceHash: hash({ text, html }) }; }
export async function listPayslips(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, payRunId?: string): Promise<Array<Record<string, unknown>>> { return sessionRunner.withBusinessSession("read", async (s) => { const result = await s.query("SELECT p.id, p.payslip_number, p.pay_run_employee_id, p.rendered_text, p.rendered_html, p.evidence_hash, r.pay_run_id, e.employee_code, e.legal_name FROM payroll_payslips p JOIN payroll_pay_run_employees r ON r.id = p.pay_run_employee_id AND r.tenant_id = p.tenant_id AND r.book_set_id = p.book_set_id JOIN payroll_employees e ON e.id = r.employee_id AND e.tenant_id = r.tenant_id AND e.book_set_id = r.book_set_id WHERE p.tenant_id = ? AND p.book_set_id = ? ORDER BY p.payslip_number, p.id", [tenantId, bookSetId]); return result.rows.filter((r) => !payRunId || String(r.pay_run_id) === payRunId); }); }

export async function createPaymentBatch(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<PayrollBankBatchPayload>): Promise<CommandResult<{ batchId: string; totalMinor: number }>> { assertEnvelope(envelope); iso(envelope.payload.paymentDate, "paymentDate"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.payment-batch.create", envelope), async () => { const bank = await s.querySingle("SELECT id FROM accounts WHERE id = ? AND tenant_id = ? AND book_set_id = ? AND archived_at IS NULL", [envelope.payload.bankAccountId, envelope.tenantId, envelope.bookSetId]); if (!bank) throw new DomainError("BANK_ACCOUNT_SCOPE_MISMATCH", "bank account does not belong to tenant and BookSet"); const batchId = envelope.payload.batchId ?? randomUUID(); let total = 0; for (const allocation of envelope.payload.allocations) { const amount = positive(allocation.amountMinor, "allocation.amountMinor"); total = safeAdd(total, amount); const runEmployee = await s.querySingle("SELECT net_minor FROM payroll_pay_run_employees e JOIN payroll_pay_runs r ON r.id = e.pay_run_id AND r.tenant_id = e.tenant_id AND r.book_set_id = e.book_set_id WHERE e.id = ? AND e.tenant_id = ? AND e.book_set_id = ? AND r.status = 'POSTED'", [allocation.payRunEmployeeId, envelope.tenantId, envelope.bookSetId]); if (!runEmployee) throw new DomainError("PAYROLL_PAYABLE_NOT_POSTED", "salary payable must come from a posted pay run"); const allocated = await s.querySingle("SELECT COALESCE(SUM(amount_minor), 0) AS total FROM payroll_payment_allocations WHERE pay_run_employee_id = ? AND tenant_id = ? AND book_set_id = ?", [allocation.payRunEmployeeId, envelope.tenantId, envelope.bookSetId]); if (amount + Number(allocated?.total ?? 0) > Number(runEmployee.net_minor)) throw new DomainError("PAYROLL_PAYMENT_OVERPAY", "salary allocation exceeds employee net payable"); } await s.execute("INSERT INTO payroll_payment_batches (id, tenant_id, book_set_id, payment_date, bank_account_id, status, created_at, journal_id) VALUES (?, ?, ?, ?, ?, 'PREPARED', ?, NULL)", [batchId, envelope.tenantId, envelope.bookSetId, envelope.payload.paymentDate, envelope.payload.bankAccountId, new Date().toISOString()]); for (const allocation of envelope.payload.allocations) await s.execute("INSERT INTO payroll_payment_allocations (id, tenant_id, book_set_id, batch_id, pay_run_employee_id, amount_minor, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [randomUUID(), envelope.tenantId, envelope.bookSetId, batchId, allocation.payRunEmployeeId, allocation.amountMinor, new Date().toISOString()]); return { batchId, totalMinor: total }; })); }

const GENERIC_FIELDS = new Set(["employeeCode", "employeeName", "bankLastFour", "amountMinor", "paymentDate", "reference"]);
export async function exportBankCsv(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<BankExportPayload>): Promise<CommandResult<{ artifactId: string; artifactHash: string; csv: string; submitted: false }>> { assertEnvelope(envelope); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.bank-export.create", envelope), async () => { const batch = await s.querySingle("SELECT id, payment_date FROM payroll_payment_batches WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.batchId, envelope.tenantId, envelope.bookSetId]); if (!batch) throw new DomainError("PAYMENT_BATCH_NOT_FOUND", "payment batch does not belong to tenant and BookSet"); let presetId = envelope.payload.presetId; if (!presetId) { const existing = await s.querySingle("SELECT id FROM payroll_bank_export_presets WHERE tenant_id = ? AND book_set_id = ? AND preset_code = 'GENERIC_NEFT' ORDER BY version DESC LIMIT 1", [envelope.tenantId, envelope.bookSetId]); if (existing) presetId = String(existing.id); else { presetId = randomUUID(); await s.execute("INSERT INTO payroll_bank_export_presets (id, tenant_id, book_set_id, preset_code, version, columns_json, created_at) VALUES (?, ?, ?, 'GENERIC_NEFT', 1, ?, ?)", [presetId, envelope.tenantId, envelope.bookSetId, canonicalJson(["employeeCode", "employeeName", "amountMinor", "paymentDate", "reference"]), new Date().toISOString()]); } } const preset = await s.querySingle("SELECT id, columns_json FROM payroll_bank_export_presets WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [presetId, envelope.tenantId, envelope.bookSetId]); if (!preset) throw new DomainError("BANK_EXPORT_PRESET_NOT_FOUND", "bank export preset does not belong to tenant and BookSet"); const fields = JSON.parse(String(preset.columns_json)) as string[]; if (!Array.isArray(fields) || fields.length === 0 || fields.some((f) => !GENERIC_FIELDS.has(f) || f === "bankAccount")) throw new DomainError("INVALID_BANK_EXPORT_PRESET", "preset contains a field outside the allowlist"); const rows = await s.query("SELECT e.employee_code, e.legal_name, e.bank_last_four, a.amount_minor, b.payment_date, a.pay_run_employee_id FROM payroll_payment_allocations a JOIN payroll_payment_batches b ON b.id = a.batch_id AND b.tenant_id = a.tenant_id AND b.book_set_id = a.book_set_id JOIN payroll_pay_run_employees r ON r.id = a.pay_run_employee_id AND r.tenant_id = a.tenant_id AND r.book_set_id = a.book_set_id JOIN payroll_employees e ON e.id = r.employee_id AND e.tenant_id = r.tenant_id AND e.book_set_id = r.book_set_id WHERE a.batch_id = ? AND a.tenant_id = ? AND a.book_set_id = ? ORDER BY e.employee_code, a.pay_run_employee_id", [envelope.payload.batchId, envelope.tenantId, envelope.bookSetId]); const header = fields.join(","); const csvRows = rows.rows.map((r) => fields.map((field) => { if (field === "employeeCode") return String(r.employee_code); if (field === "employeeName") return String(r.legal_name); if (field === "bankLastFour") return `****${String(r.bank_last_four ?? "").slice(-4)}`; if (field === "amountMinor") return String(r.amount_minor); if (field === "paymentDate") return String(r.payment_date); return `PAYROLL-${String(r.pay_run_employee_id)}`; }).join(",")); const csv = [header, ...csvRows].join("\n"); const artifactHash = hash({ batchId: envelope.payload.batchId, presetId, fields, csv }); const artifactId = randomUUID(); await s.execute("INSERT INTO payroll_bank_export_artifacts (id, tenant_id, book_set_id, batch_id, preset_id, csv_text, artifact_hash, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)", [artifactId, envelope.tenantId, envelope.bookSetId, envelope.payload.batchId, presetId, csv, artifactHash, new Date().toISOString()]); return { artifactId, artifactHash, csv, submitted: false as const }; })); }

export async function createRemittance(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<RemittancePayload>): Promise<CommandResult<{ remittanceId: string; status: "PREPARED" }>> { assertEnvelope(envelope); positive(envelope.payload.amountMinor, "amountMinor"); iso(envelope.payload.periodStart, "periodStart"); iso(envelope.payload.periodEnd, "periodEnd"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.remittance.create", envelope), async () => { await payableAccounts(s, envelope, [envelope.payload.liabilityAccountId]); await payrollAccount(s, envelope, envelope.payload.liabilityAccountId, "LIABILITY"); const id = envelope.payload.remittanceId ?? randomUUID(); await s.execute("INSERT INTO payroll_remittances (id, tenant_id, book_set_id, rule_type, period_start, period_end, liability_account_id, amount_minor, status, evidence_id, observation, created_at, journal_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'PREPARED', NULL, NULL, ?, NULL)", [id, envelope.tenantId, envelope.bookSetId, envelope.payload.ruleType, envelope.payload.periodStart, envelope.payload.periodEnd, envelope.payload.liabilityAccountId, envelope.payload.amountMinor, new Date().toISOString()]); return { remittanceId: id, status: "PREPARED" as const }; })); }
export async function updateRemittance(sessionRunner: BusinessSessionRunner, envelope: PayrollCommandEnvelope<RemittanceActionPayload>): Promise<CommandResult<{ remittanceId: string; status: string }>> { assertEnvelope(envelope); if (envelope.payload.status === "ACKNOWLEDGED" && !envelope.payload.evidenceId) throw new DomainError("REMITTANCE_ACK_EVIDENCE_REQUIRED", "acknowledged remittances require acknowledgement evidence"); return sessionRunner.withBusinessSession("write", async (s) => idempotent(s, envelope, payloadHash("payroll.remittance.update", envelope), async () => { const r = await s.querySingle("SELECT id, status FROM payroll_remittances WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.remittanceId, envelope.tenantId, envelope.bookSetId]); if (!r) throw new DomainError("REMITTANCE_NOT_FOUND", "remittance does not belong to tenant and BookSet"); const order = ["PREPARED", "EXPORTED", "SUBMITTED", "ACKNOWLEDGED", "REJECTED"]; if (envelope.payload.status !== "REJECTED" && order.indexOf(envelope.payload.status) <= order.indexOf(String(r.status))) throw new DomainError("INVALID_REMITTANCE_STATE", "remittance state cannot move backward"); await s.execute("UPDATE payroll_remittances SET status = ?, evidence_id = COALESCE(?, evidence_id), observation = ? WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [envelope.payload.status, envelope.payload.evidenceId ?? null, envelope.payload.observation ?? null, envelope.payload.remittanceId, envelope.tenantId, envelope.bookSetId]); return { remittanceId: envelope.payload.remittanceId, status: envelope.payload.status }; })); }

export async function payrollRegister(sessionRunner: BusinessSessionRunner, tenantId: TenantId, bookSetId: BookSetId, periodStart?: string, periodEnd?: string): Promise<Array<Record<string, unknown>>> { return sessionRunner.withBusinessSession("read", async (s) => { const result = await s.query("SELECT r.id, r.period_start, r.period_end, r.payment_date, r.status, r.calculation_hash, e.employee_code, e.legal_name, e.gross_minor, e.employee_deduction_minor, e.employer_contribution_minor, e.net_minor FROM payroll_pay_runs r JOIN payroll_pay_run_employees e ON e.pay_run_id = r.id AND e.tenant_id = r.tenant_id AND e.book_set_id = r.book_set_id WHERE r.tenant_id = ? AND r.book_set_id = ? ORDER BY r.period_start, r.id, e.employee_code", [tenantId, bookSetId]); return result.rows.filter((r) => (!periodStart || String(r.period_end) >= periodStart) && (!periodEnd || String(r.period_start) <= periodEnd)); }); }
